-- Initial demo-snapshot audit, not a migration or audit of a subsequently edited demo.
-- Read-only against application tables. Fails atomically inside demo_reset.sql.
\set ON_ERROR_STOP on
DO $$
DECLARE n bigint; fixture_record record; player_record record; debt jsonb := '{}'::jsonb;
        yellows jsonb := '{}'::jsonb; key text; old_y int; new_y int; amount int;
        expected_tables text[] := ARRAY['users','managers','staff','players','tournaments','seasons','rules','rounds','matches','stadiums','clubs','match_clubs','club_players','match_players','events','goals','fouls','yellow_cards','red_cards','substitutions'];
BEGIN
    SELECT count(*) INTO n FROM information_schema.tables WHERE table_schema=current_schema() AND table_type='BASE TABLE';
    IF n<>20 OR EXISTS(SELECT 1 FROM unnest(expected_tables) t WHERE to_regclass(t) IS NULL) THEN RAISE EXCEPTION 'Expected exactly the20 application tables in current schema'; END IF;
    IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=current_schema() AND (table_name,column_name) IN (('users','source_key'),('rounds','round_number'),('matches','match_number'),('match_players','is_simulated'),('events','is_simulated'))) THEN RAISE EXCEPTION 'Obsolete persistent metadata remains'; END IF;
    IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=current_schema() AND table_name='seasons' AND column_name='name') THEN RAISE EXCEPTION 'seasons.name missing'; END IF;
    IF (SELECT count(*) FROM tournaments)<>1 OR (SELECT count(*) FROM seasons)<>5 OR (SELECT count(*) FROM clubs)<>14 OR (SELECT count(*) FROM rounds)<>26 OR (SELECT count(*) FROM matches)<>182 OR (SELECT count(*) FROM players)<>316 OR (SELECT count(*) FROM users)<>332 OR (SELECT count(*) FROM staff)<>1 OR (SELECT count(*) FROM managers)<>14 THEN RAISE EXCEPTION 'Demo cardinality mismatch'; END IF;
    IF (SELECT count(*) FROM rules)<>1 OR NOT EXISTS(SELECT 1 FROM rules WHERE id=1 AND required_main_players=11 AND max_bench_players=9 AND max_substitutions=5 AND yellow_cards_to_suspend=3 AND age_limit=45 AND max_foreign_players=3) THEN RAISE EXCEPTION 'Consumer rule mismatch'; END IF;
    IF EXISTS(SELECT 1 FROM rounds WHERE season_id<>1 OR name<>'Vòng '||id) OR EXISTS(SELECT 1 FROM rounds r LEFT JOIN matches m ON m.round_id=r.id GROUP BY r.id HAVING count(m.id)<>7) THEN RAISE EXCEPTION 'Main round fixture shape mismatch'; END IF;
    IF EXISTS(SELECT 1 FROM seasons old JOIN seasons main ON main.id=1 WHERE old.id<>1 AND (old.end_date>=main.start_date OR EXISTS(SELECT 1 FROM rounds WHERE season_id=old.id))) THEN RAISE EXCEPTION 'Historical seasons overlap or contain fixtures'; END IF;
    IF EXISTS(SELECT 1 FROM matches m JOIN rounds r ON r.id=m.round_id JOIN seasons s ON s.id=r.season_id WHERE m.kickoff_time IS NULL OR m.kickoff_time::date<s.start_date OR m.kickoff_time::date>s.end_date OR (r.id<=6 AND m.status<>'FINISHED') OR (r.id>=7 AND m.status<>'SCHEDULED')) THEN RAISE EXCEPTION 'Shifted calendar/status mismatch'; END IF;
    -- Anchor recoverable from the stored schedule, so a fixed-date audit need not use today.
    IF (SELECT min(kickoff_time)::date FROM matches WHERE round_id=7)<>(SELECT start_date+49 FROM seasons WHERE id=1) OR EXISTS(SELECT 1 FROM matches WHERE round_id<=6 AND kickoff_time::date>=(SELECT start_date+42 FROM seasons WHERE id=1)) THEN RAISE EXCEPTION 'Round7 must be anchor+7; historical rounds precede anchor'; END IF;
    IF EXISTS(SELECT 1 FROM matches m LEFT JOIN match_clubs mc ON mc.match_id=m.id GROUP BY m.id HAVING count(mc.id)<>2 OR count(*) FILTER(WHERE role='HOME')<>1 OR count(*) FILTER(WHERE role='AWAY')<>1 OR count(DISTINCT club_id)<>2) THEN RAISE EXCEPTION 'HOME/AWAY pair invariant'; END IF;
    IF (SELECT count(*) FROM club_players)<>316 OR EXISTS(SELECT 1 FROM club_players GROUP BY club_id,shirt_number HAVING count(*)<>1) OR EXISTS(SELECT 1 FROM club_players GROUP BY player_id HAVING count(*)<>1) THEN RAISE EXCEPTION 'Club membership/shirt uniqueness'; END IF;
    IF EXISTS(SELECT 1 FROM users u JOIN players p ON p.user_id=u.id WHERE u.dob IS NULL OR p.nationality='' OR p.height_cm<=0 OR p.weight_kg<=0) THEN RAISE EXCEPTION 'Incomplete sourced player'; END IF;
    IF NOT EXISTS(SELECT 1 FROM users WHERE username='CT001' AND id=17 AND password_hash=crypt('player@123',password_hash)) OR NOT EXISTS(SELECT 1 FROM users u JOIN staff st ON st.user_id=u.id WHERE username='NV001' AND password_hash=crypt('staff@123',password_hash)) OR NOT EXISTS(SELECT 1 FROM users u JOIN managers ma ON ma.user_id=u.id WHERE username='QL001' AND password_hash=crypt('manager@123',password_hash)) OR NOT EXISTS(SELECT 1 FROM users u WHERE username='khangia' AND password_hash=crypt('spectator@123',password_hash) AND NOT EXISTS(SELECT 1 FROM players WHERE user_id=u.id) AND NOT EXISTS(SELECT 1 FROM managers WHERE user_id=u.id) AND NOT EXISTS(SELECT 1 FROM staff WHERE user_id=u.id)) THEN RAISE EXCEPTION 'Demo account roles/hashes'; END IF;
    IF (SELECT last_value FROM player_code_seq)<>316 OR NOT (SELECT is_called FROM player_code_seq) THEN RAISE EXCEPTION 'Next generated player code must be CT317'; END IF;
    IF EXISTS(SELECT 1 FROM match_players mp JOIN match_clubs mc ON mc.id=mp.match_club_id JOIN club_players cp ON cp.id=mp.club_player_id WHERE mc.club_id<>cp.club_id) THEN RAISE EXCEPTION 'Registration belongs to another club'; END IF;
    IF EXISTS(SELECT 1 FROM match_players mp JOIN match_clubs mc ON mc.id=mp.match_club_id JOIN club_players cp ON cp.id=mp.club_player_id GROUP BY mc.match_id,cp.player_id HAVING count(*)<>1) THEN RAISE EXCEPTION 'Duplicate player in fixture'; END IF;
    IF EXISTS(SELECT 1 FROM match_clubs mc JOIN matches m ON m.id=mc.match_id WHERE m.status='FINISHED' AND NOT EXISTS(SELECT 1 FROM match_players WHERE match_club_id=mc.id)) THEN RAISE EXCEPTION 'Finished fixture missing lineup'; END IF;
    FOR fixture_record IN SELECT mc.id,s.start_date,ru.max_bench_players,ru.max_foreign_players,ru.age_limit FROM match_clubs mc JOIN matches m ON m.id=mc.match_id JOIN rounds r ON r.id=m.round_id JOIN seasons s ON s.id=r.season_id JOIN rules ru ON ru.id=s.rule_id WHERE EXISTS(SELECT 1 FROM match_players WHERE match_club_id=mc.id) LOOP
        SELECT count(*) INTO n FROM match_players WHERE match_club_id=fixture_record.id AND role='STARTING';
        IF n<>11 OR NOT EXISTS(SELECT 1 FROM match_players mp JOIN club_players cp ON cp.id=mp.club_player_id JOIN players p ON p.user_id=cp.player_id WHERE mp.match_club_id=fixture_record.id AND mp.role='STARTING' AND p.primary_position='Thủ môn') THEN RAISE EXCEPTION 'Starting/GK invariant for side %',fixture_record.id; END IF;
        IF (SELECT count(*) FROM match_players WHERE match_club_id=fixture_record.id AND role='SUBSTITUTE')>fixture_record.max_bench_players OR (SELECT count(*) FROM match_players mp JOIN club_players cp ON cp.id=mp.club_player_id JOIN players p ON p.user_id=cp.player_id WHERE mp.match_club_id=fixture_record.id AND lower(trim(p.nationality))<>lower('Việt Nam'))>fixture_record.max_foreign_players OR EXISTS(SELECT 1 FROM match_players mp JOIN club_players cp ON cp.id=mp.club_player_id JOIN users u ON u.id=cp.player_id WHERE mp.match_club_id=fixture_record.id AND (u.dob>fixture_record.start_date OR extract(year FROM age(fixture_record.start_date,u.dob))>fixture_record.age_limit)) THEN RAISE EXCEPTION 'Quota/age invariant for side %',fixture_record.id; END IF;
    END LOOP;
    -- Replay discipline at each club kickoff. Eligibility is checked BEFORE a finished
    -- match serves outstanding debt, then that match's cards add new debt.
    FOR fixture_record IN SELECT m.id,m.status,m.kickoff_time,mc.id AS side,mc.club_id FROM matches m JOIN match_clubs mc ON mc.match_id=m.id ORDER BY m.kickoff_time,m.id,mc.id LOOP
        FOR player_record IN SELECT cp.player_id FROM match_players mp JOIN club_players cp ON cp.id=mp.club_player_id WHERE mp.match_club_id=fixture_record.side LOOP
            key:=fixture_record.club_id||':'||player_record.player_id;
            IF coalesce((debt->>key)::int,0)>0 THEN RAISE EXCEPTION 'Suspended player % registered in match %',player_record.player_id,fixture_record.id; END IF;
        END LOOP;
        IF fixture_record.status='FINISHED' THEN
            FOR player_record IN SELECT cp.player_id FROM club_players cp WHERE cp.club_id=fixture_record.club_id LOOP
                key:=fixture_record.club_id||':'||player_record.player_id;
                debt:=jsonb_set(debt,ARRAY[key],to_jsonb(greatest(0,coalesce((debt->>key)::int,0)-1)));
            END LOOP;
        END IF;
        FOR player_record IN SELECT cp.player_id,count(y.id)::int AS yc,count(rc.id)::int AS rc FROM match_players mp JOIN club_players cp ON cp.id=mp.club_player_id LEFT JOIN events e ON e.match_player_id=mp.id LEFT JOIN yellow_cards y ON y.id=e.id LEFT JOIN red_cards rc ON rc.id=e.id WHERE mp.match_club_id=fixture_record.side GROUP BY cp.player_id LOOP
            key:=fixture_record.club_id||':'||player_record.player_id; old_y:=coalesce((yellows->>key)::int,0);new_y:=old_y+player_record.yc;
            yellows:=jsonb_set(yellows,ARRAY[key],to_jsonb(new_y));
            amount:=new_y/3-old_y/3+player_record.rc;
            debt:=jsonb_set(debt,ARRAY[key],to_jsonb(coalesce((debt->>key)::int,0)+amount));
        END LOOP;
    END LOOP;
    IF coalesce((debt->>'12:257')::int,0)<>0 OR coalesce((debt->>'12:258')::int,0)<>1 OR coalesce((debt->>'12:259')::int,0)<>1 THEN RAISE EXCEPTION 'Exact served/yellow/red pending scenarios mismatch'; END IF;
    IF EXISTS(SELECT 1 FROM match_players mp JOIN match_clubs mc ON mc.id=mp.match_club_id JOIN matches m ON m.id=mc.match_id JOIN club_players cp ON cp.id=mp.club_player_id WHERE cp.player_id=257 AND m.round_id IN (4,5)) OR NOT EXISTS(SELECT 1 FROM match_players mp JOIN match_clubs mc ON mc.id=mp.match_club_id JOIN matches m ON m.id=mc.match_id JOIN club_players cp ON cp.id=mp.club_player_id WHERE cp.player_id=257 AND m.round_id=6) THEN RAISE EXCEPTION 'Stacked two-fixture suspension not served correctly'; END IF;
    IF EXISTS(SELECT 1 FROM match_players mp JOIN match_clubs mc ON mc.id=mp.match_club_id WHERE mc.match_id=43) OR (SELECT count(*) FROM match_players WHERE match_club_id=87)<>14 OR EXISTS(SELECT 1 FROM match_players WHERE match_club_id=88) THEN RAISE EXCEPTION 'Open both/replacement walkthrough mismatch'; END IF;
    IF (SELECT count(*) FROM match_players)<>1190 OR (SELECT count(*) FROM events)<>14 OR (SELECT count(*) FROM goals)<>4 OR (SELECT count(*) FROM fouls)<>1 OR (SELECT count(*) FROM yellow_cards)<>6 OR (SELECT count(*) FROM red_cards)<>2 OR (SELECT count(*) FROM substitutions)<>1 THEN RAISE EXCEPTION 'Initial scenario event/lineup cardinality mismatch'; END IF;
    IF EXISTS(SELECT 1 FROM events e LEFT JOIN goals g ON g.id=e.id LEFT JOIN fouls f ON f.id=e.id LEFT JOIN yellow_cards y ON y.id=e.id LEFT JOIN red_cards rc ON rc.id=e.id LEFT JOIN substitutions s ON s.id=e.id WHERE (g.id IS NOT NULL)::int+(f.id IS NOT NULL)::int+(y.id IS NOT NULL)::int+(rc.id IS NOT NULL)::int+(s.id IS NOT NULL)::int<>1) THEN RAISE EXCEPTION 'Event subtype must be exactly1'; END IF;
    IF EXISTS(SELECT 1 FROM events e JOIN match_players mp ON mp.id=e.match_player_id JOIN match_clubs mc ON mc.id=mp.match_club_id WHERE mc.match_id<>e.match_id OR mp.role<>'STARTING' OR e.minute>90 OR e.minute<0) THEN RAISE EXCEPTION 'Event actor/match/timing invariant'; END IF;
    IF EXISTS(SELECT 1 FROM goals g JOIN events e ON e.id=g.id JOIN match_players actor ON actor.id=e.match_player_id LEFT JOIN match_players assister ON assister.id=g.assister_id WHERE g.assister_id=e.match_player_id OR (g.assister_id IS NOT NULL AND (g.goal_type<>'NORMAL' OR assister.match_club_id<>actor.match_club_id))) OR NOT EXISTS(SELECT 1 FROM goals WHERE goal_type='NORMAL' AND assister_id IS NULL) OR NOT EXISTS(SELECT 1 FROM goals WHERE goal_type='NORMAL' AND assister_id IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM goals WHERE goal_type='PENALTY') OR NOT EXISTS(SELECT 1 FROM goals WHERE goal_type='OWN') THEN RAISE EXCEPTION 'Goal/assist scenarios'; END IF;
    IF EXISTS(SELECT 1 FROM fouls fo JOIN events e ON e.id=fo.id JOIN match_players a ON a.id=e.match_player_id JOIN match_players v ON v.id=fo.victim_id JOIN match_clubs vm ON vm.id=v.match_club_id WHERE a.match_club_id=v.match_club_id OR vm.match_id<>e.match_id) THEN RAISE EXCEPTION 'Foul victim invariant'; END IF;
    IF EXISTS(SELECT 1 FROM substitutions s JOIN events e ON e.id=s.id JOIN match_players a ON a.id=e.match_player_id JOIN match_players pin ON pin.id=s.player_in_id WHERE a.match_club_id<>pin.match_club_id OR pin.role<>'SUBSTITUTE' OR a.id=pin.id) OR EXISTS(SELECT 1 FROM events later JOIN events earlier ON earlier.match_id=later.match_id AND earlier.match_player_id=later.match_player_id AND (earlier.minute,earlier.extra_minute,earlier.id)<(later.minute,later.extra_minute,later.id) WHERE EXISTS(SELECT 1 FROM substitutions WHERE id=earlier.id) OR EXISTS(SELECT 1 FROM red_cards WHERE id=earlier.id)) THEN RAISE EXCEPTION 'Substitution/red on-field timeline invariant'; END IF;
    IF (SELECT count(*) FROM goals g JOIN events e ON e.id=g.id JOIN match_players mp ON mp.id=e.match_player_id JOIN match_clubs mc ON mc.id=mp.match_club_id WHERE e.match_id=1 AND ((mc.role='HOME' AND g.goal_type<>'OWN') OR (mc.role='AWAY' AND g.goal_type='OWN')))<>3 OR (SELECT count(*) FROM goals g JOIN events e ON e.id=g.id JOIN match_players mp ON mp.id=e.match_player_id JOIN match_clubs mc ON mc.id=mp.match_club_id WHERE e.match_id=1 AND ((mc.role='AWAY' AND g.goal_type<>'OWN') OR (mc.role='HOME' AND g.goal_type='OWN')))<>1 OR EXISTS(SELECT 1 FROM events WHERE match_id=2) THEN RAISE EXCEPTION 'Exact derived scores3–1 and0–0'; END IF;
    -- Lock predicates exercised by the consumer: FINISHED, past kickoff and event presence.
    IF NOT EXISTS(SELECT 1 FROM matches WHERE id=1 AND status='FINISHED' AND EXISTS(SELECT 1 FROM events WHERE match_id=1)) OR EXISTS(SELECT 1 FROM matches WHERE id IN (43,44) AND (status<>'SCHEDULED' OR EXISTS(SELECT 1 FROM events WHERE match_id=matches.id))) THEN RAISE EXCEPTION 'Consumer lock/open fixture scenarios'; END IF;
    -- Stable match ordinal is assigned over the whole round before any keyword filter.
    SELECT count(*) INTO n FROM (SELECT m.id,row_number() OVER(PARTITION BY round_id ORDER BY m.id) AS ordinal FROM matches m) numbered WHERE id=43 AND ordinal=1;
    IF n<>1 OR NOT EXISTS(SELECT 1 FROM rounds WHERE id=7 AND name='Vòng 7') THEN RAISE EXCEPTION 'R07/R07-T01 identity contract'; END IF;
    RAISE NOTICE 'Demo initial snapshot assertions passed:316 players,26 rounds,182 fixtures; exact scenario manifest matched.';
END $$;
